 for(const side of ['player','enemy']){const fighter=arena.querySelector('.fighter-'+side),v=frame[side];if(!fighter||!v)continue;
  const num=fighter.querySelector('.hpnum'),bar=fighter.querySelector('.health');if(num)num.textContent=n(v.hp)+' / '+n(v.max);updateHealthBar(bar,hpPercent(v.hp,v.max),{reduced:matchMedia('(prefers-reduced-motion: reduce)').matches});
 }
 const state=arena.querySelector('.actual-enemy-state');if(state)state.textContent=frame.mirror?frame.mirror.text:frame.armor?'黒晶殻'+(frame.tactical?' ／ 羽弾系×0.35':''):frame.exposed?'殻解除・露出 '+frame.exposed+'T（最終補正×1.6）':'殻なし';
 const phase=arena.querySelector('.fighter-enemy .info>small');if(phase)phase.textContent='第'+frame.phase+'形態 / 侵食 '+Math.round((frame.erosion||0)*100)+'%';
 if(frame.mirror){arena.classList.toggle('mirror-awake',frame.mirror.awake);arena.classList.toggle('mirror-unsealed',frame.mirror.unsealed);arena.style.setProperty('--mirror-arena',`url('${frame.mirror.unsealed?MIRROR_ART.beyond:MIRROR_ART.arena}')`);const player=arena.querySelector('.fighter-player img');if(player&&frame.mirror.unsealed)player.src=MIRROR_ART.releaseSprite;const im=arena.querySelector('.fighter-enemy img');if(im)im.src=frame.mirror.unsealed?MIRROR_ART.phase3:frame.mirror.awake?MIRROR_ART.phase2:MIRROR_ART.red;}
 const gauge=$('.battle-charge .gaugebar span');if(gauge)gauge.style.width=frame.gauge+'%';const value=$('.battle-charge .gold');if(value)value.textContent=frame.gauge+'%';
