async function doPresentedCombat(b,id,route){
 if(combatRecovering||b!==battle||b.result)return;
 combatRecovering=true;clearTimeout(combatReleaseTimer);syncCombatBusy();const controller=new AbortController(),events=[];
 try{
  const before=combatFrame(b);
  observeCombat(b,e=>events.push(e),()=>{if(b.lab20)actLab20(b,id,{route});else if(b.main20)actMainBattle(b,id,{route});else if(b.campaign)actCampaign(b,id,{route});else if(b.trial?.kind==='mirror')actMirrorTrial(b,id,{route});else if(b.trial?.kind==='guard-break')actGuardBreakTrial(b,id,{route});else if(b.trial)actThreePhase(b,id,{route});else act(b,id,{route});});b.lastAction=id;if(b.trial?.kind==='mirror')persistMirror(b);
  if(b.result){b.reward=b.lab20?settleLab20(lab20Run,b):b.main20?settleMainBattle(current(),b):b.campaign?settleCampaign(campaign,b):settle(current(),b);if(!b.test&&b.result==='win'&&id==='ultimate'&&b.used.marks.includes('starfall')){current().records.starfinish=true;achievements(current());}if(!b.lab20&&(!b.campaign||b.main20)&&(!b.test||sandbox))persist();}
  if(!b.result&&!b.test)persist();
  await combatVfxReady;showCombatFrame(before);
  const presentation=playCombatPresentation({arena:$('.battle-stage'),events,action:id,authority:b.powers[0],before,onFrame:showCombatFrame,onSound:tone,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,signal:controller.signal});await presentation.done;if(b.trial?.kind==='mirror'&&b.result==='win')await playMirrorMoment('victory',{reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,signal:controller.signal}).done;
 }catch(e){console.error('Combat presentation failed',e);toast('戦闘表示を復帰しました：'+e.message);}
 finally{controller.abort();combatRecovering=false;if(b===battle)render();syncCombatBusy();}
}
function download(filename,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function importFile(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>2000000)throw Error('ファイルが大きすぎます（上限2MB）');const data=validateMain20(JSON.parse(await file.text()));modal('セーブを復元',`<p>Lv.${data.level} / 到達Lv.${data.floor} / ${data.achieved.length}実績のデータです。${sandbox?'試験用':'本編'}セーブを上書きします。読み込み前のバックアップを書き出せます。</p>`,button('現在のJSONを書き出し','export','','ghost')+button('このデータに置き換える','confirmImport','','primary'));$('#modal').querySelector('[data-action="confirmImport"]').onclick=event=>{event.stopPropagation();if(battle&&!battle.result){toast('進行中の戦闘を撤退してから読み込んでください');return;}if(sandbox)sandbox=data;else s=data;saveBlocked=false;battle=sandbox?null:restoreMarkBattle(s.markBattle,validateSave);page='home';const stored=persist();close();render();toast(stored?'JSONから復元しました':'JSONを読み込みましたが、端末への保存に失敗しました。JSONバックアップを保持してください。');};}catch(e){toast('読み込み失敗：'+e.message);}};input.click();}
async function handle(action,id){if(sortieActive||combatAnimating||combatRecovering)return;const a=current();if(action==='mirrorStart'&&!mirrorEntryAllowed(a.level,!!sandbox))throw Error('鏡像戦は育成Lv.20で解放されます');switch(action){
