/* Supplied-character combat showcase: portraits are not substitute SVGs anymore. */
.battle-stage{isolation:isolate;min-height:390px;background:radial-gradient(ellipse at 28% 24%,#5e426b52,transparent 52%),radial-gradient(ellipse at 76% 60%,#5130444d,transparent 60%),linear-gradient(150deg,#111629,#080c19);border-color:#6a506a82}
.battle-stage.stage-divine{background:radial-gradient(ellipse at 23% 20%,#d9af6e38,transparent 62%),linear-gradient(145deg,#22223d,#0c1227)}
.battle-stage.stage-fallen{background:radial-gradient(ellipse at 24% 20%,#ac29473d,transparent 64%),linear-gradient(145deg,#291827,#0c101d)}
.battle-stage.stage-neutral{background:radial-gradient(ellipse at 24% 20%,#a57f7540,transparent 64%),linear-gradient(145deg,#2c2436,#0d1123)}
.battle-stage.stage-stella{background:radial-gradient(ellipse at 22% 20%,#8c405f45,transparent 64%),linear-gradient(145deg,#281a38,#0c152b)}
.battle-stage .fighter{gap:7px;justify-content:flex-end}
.battle-stage .fighter h3{z-index:2;text-shadow:0 2px 12px #040613;min-height:24px}
.battle-stage .portrait-frame{position:relative;width:100%;height:280px;min-height:0;overflow:hidden;border-radius:12px 12px 6px 6px;background:radial-gradient(ellipse at center,#292035,#0c1022);box-shadow:inset 0 0 0 1px #e9d19a26,0 12px 26px #05071450}
.battle-stage .portrait-frame::after{content:'';position:absolute;inset:0;pointer-events:none;background:linear-gradient(to bottom,#060c1800 55%,#0c1223ad 100%);border:1px solid #ddd2df22;border-radius:inherit}
.battle-stage .fighter .sprite.portrait{height:100%;width:100%;object-fit:cover;object-position:center 27%;display:block;filter:none;transform:none}
.battle-stage .fighter .sprite.portrait-alpha{object-fit:contain;object-position:center 50%;filter:drop-shadow(0 10px 15px #09071166)}
.battle-stage .portrait-foe{display:grid;place-items:center}
.battle-stage .portrait-foe .sprite{height:100%;width:100%;filter:drop-shadow(0 0 28px #c36b9e5e)}
.battle-stage .fighter .info{z-index:2;position:relative;border-color:#84719177;box-shadow:0 6px 18px #04081544}
.battle-stage .fighter-player .info{border-top-color:#e8cf9d88}
.battle-stage .fighter-enemy .info{border-top-color:#dd7d9780}
.battle-stage .portrait-frame .portrait{animation:portrait-arrive .55s cubic-bezier(.19,.7,.2,1) both}
@keyframes portrait-arrive{from{opacity:.55;transform:scale(1.045)}to{opacity:1;transform:scale(1)}}
.result-illustrated{min-height:250px;display:flex;justify-content:center;align-items:center;isolation:isolate;overflow:hidden;background:linear-gradient(90deg,#131523,#221627)}
.result-illustrated .result-art{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 35%;opacity:.59;z-index:-2}
.result-illustrated::before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,#101325ea,#101325b8 48%,#10132577);z-index:-1}
.result .result-content{position:relative;z-index:1;width:100%}
.result-illustrated h2{font-size:clamp(30px,5vw,52px);font-weight:850;letter-spacing:.17em;text-shadow:0 2px 24px #000}
.result-illustrated .small{color:#fff1e0;text-shadow:0 1px 8px #080916}
.result-illustrated .row{justify-content:center}
#cinema.cut .cinema-copy{text-shadow:0 3px 20px #000,0 0 24px #000;z-index:1}
#cinema.cut .cinema-copy h2{font-size:clamp(44px,8vw,100px);color:#fff5e1;letter-spacing:.16em;line-height:1.2}
#cinema.cut img{max-width:none;max-height:none;width:100%;height:100%;right:0;object-fit:cover;object-position:50% 34%;opacity:.83;animation:cutin-enter .6s cubic-bezier(.12,.72,.2,1) both}
#cinema.cut:before{content:'';position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(90deg,#0b101fcf,transparent 74%),linear-gradient(0deg,#0b101f85,transparent 60%)}
@keyframes cutin-enter{from{opacity:.4;transform:scale(1.12) translateX(3%)}to{opacity:.83;transform:scale(1) translateX(0)}}
@media(max-width:700px){
 .battle-stage{min-height:335px;padding:12px 8px;gap:9px}
 .battle-stage .portrait-frame{height:225px;border-radius:12px}
 .battle-stage .fighter .sprite.portrait{object-position:center 24%}
 .battle-stage .fighter .info{padding:7px 6px}
 .battle-stage .fighter h3{min-height:29px;font-size:12px}
 .result-illustrated{min-height:235px}
