/* Keep the victory illustration inside its card, never over the entire page. */
.result-illustrated{position:relative}
/* The existing one-second reveal finished after the short cut-in; show the attack name immediately. */
#cinema.cut .cinema-copy{position:relative;z-index:2;animation:cut-label-in .18s ease-out both}
@keyframes cut-label-in{from{opacity:.3;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
@media(prefers-reduced-motion:reduce){#cinema.cut .cinema-copy{animation:none}}

/* Soft white sword trails are purely visual and never affect hit calculations. */
.battle-stage .blade-strike{position:absolute;inset:0;z-index:5;pointer-events:none;overflow:hidden;border-radius:inherit;animation:blade-flash .52s ease-out both}
.blade-strike svg{height:100%;width:100%;overflow:visible;filter:drop-shadow(0 0 8px #e8f7ff)}
.blade-strike path{fill:none;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke;stroke-dasharray:160;stroke-dashoffset:160;animation:blade-sweep .42s cubic-bezier(.15,.7,.3,1) both}
.blade-strike .blade-halo{stroke:#c8eaff;stroke-width:16;opacity:.55;filter:blur(7px)}
.blade-strike .blade-core{stroke:#fff;stroke-width:4;filter:drop-shadow(0 0 5px #fff)}
.blade-strike .blade-second{stroke:#f9ffff;stroke-width:2.6;opacity:.85;animation-delay:.06s}
@keyframes blade-sweep{0%{stroke-dashoffset:160;opacity:.1}42%{stroke-dashoffset:0;opacity:1}100%{stroke-dashoffset:0;opacity:.15}}
@keyframes blade-flash{0%{opacity:0}20%{opacity:1}75%{opacity:1}100%{opacity:0}}
/* A short side-select cinematic: dim for Fallen, radiant for Divine. */
#cinema.alignment{overflow:hidden;isolation:isolate;background:#08090e;--alignment-ink:#ff9daf}
#cinema.alignment-divine{background:#f8edce;--alignment-ink:#fff4cf}
#cinema.alignment .alignment-tint{position:absolute;inset:0;background:radial-gradient(ellipse at center,#671728b0,#05040ae8 80%);animation:alignment-hold .2s ease-in both}
#cinema.alignment-divine .alignment-tint{background:radial-gradient(ellipse at center,#fff8dc,#e5bf7ca8 70%,#6f593e8a);animation:alignment-hold .2s ease-in both}
@keyframes alignment-hold{from{opacity:.15}to{opacity:1}}
#cinema.alignment .alignment-crest{position:absolute;width:min(84vmin,600px);height:min(84vmin,600px);object-fit:contain;left:50%;top:47%;transform:translate(-50%,-50%);opacity:.36;filter:drop-shadow(0 0 18px #ff244d);mix-blend-mode:screen}
#cinema.alignment-divine .alignment-crest{opacity:.8;filter:drop-shadow(0 0 18px #d39e46);mix-blend-mode:multiply}
#cinema.alignment .alignment-portrait{position:absolute;width:min(74vw,490px);height:85dvh;max-height:850px;object-fit:contain;object-position:bottom center;bottom:0;left:50%;opacity:0;transform:translateX(-50%) scale(.94);filter:drop-shadow(0 0 25px #190b21);transition:opacity .28s,transform .55s cubic-bezier(.16,.7,.2,1)}
#cinema.alignment.revealed .alignment-portrait{opacity:1;transform:translateX(-50%) scale(1)}
#cinema.alignment .alignment-title{position:absolute;z-index:2;bottom:23%;left:50%;transform:translateX(-50%);font-family:var(--serif);color:var(--alignment-ink);font-size:clamp(38px,8vw,94px);font-weight:850;letter-spacing:.25em;white-space:nowrap;text-shadow:0 3px 16px #07030a,0 0 20px #7a244f;opacity:0;transition:opacity .2s}
#cinema.alignment-divine .alignment-title{text-shadow:0 3px 16px #68552d,0 0 18px #dbaa48}
#cinema.alignment.revealed .alignment-title{opacity:1}
@media(max-width:700px){#cinema.alignment .alignment-portrait{width:95vw;height:76dvh}#cinema.alignment .alignment-crest{width:115vw;height:115vw;max-width:560px;max-height:560px}#cinema.alignment .alignment-title{bottom:23%;font-size:clamp(37px,12vw,62px)}}
@media(prefers-reduced-motion:reduce){.battle-stage .blade-strike{animation:none;opacity:.6}.blade-strike path{animation:none;stroke-dashoffset:0}#cinema.alignment .alignment-tint{animation:none}#cinema.alignment .alignment-portrait,#cinema.alignment .alignment-title{transition:none}}

