/* Approved home composition. Every selector is scoped to the home screen. */
.home-shell{--serif:Georgia,'Yu Mincho','Hiragino Mincho ProN',serif;background:radial-gradient(ellipse at 55% 10%,#3b17343d,transparent 58%),#0b0b15}
.home-topbar{height:auto;min-height:100px;display:grid;grid-template-columns:minmax(150px,1.5fr) auto minmax(120px,1fr) auto;gap:6px 18px;padding:15px 28px 18px;background:linear-gradient(100deg,#090911ee,#18101ae6);border-color:#b7897a80;position:relative;z-index:1}
.home-wordmark{font-family:var(--serif);color:#fff1fa;min-width:0;text-shadow:0 0 18px #a648c4;white-space:nowrap}
.home-wordmark>span{font-size:clamp(18px,2.1vw,32px);letter-spacing:.015em;line-height:1.1}
.home-wordmark b{font-weight:400;color:#ecb5ff}
.home-wordmark>small{display:block;text-align:center;color:#e3d5e9;font-size:11px;letter-spacing:.1em;margin-top:6px}
.home-profile{display:flex;align-items:center;gap:9px;min-width:0}
.home-profile img{width:42px;height:42px;object-fit:cover;object-position:52% 28%;border:1px solid #dfbf82;border-radius:50%;box-shadow:0 0 12px #ad579a44}
.home-profile small,.home-profile strong{display:block;line-height:1.5;color:#f7edf3;white-space:nowrap}
.home-profile strong{font-size:14px;font-weight:600}
.home-wallet{display:grid;gap:1px;font-variant-numeric:tabular-nums;min-width:0}
.home-wallet>span{display:flex;align-items:center;gap:7px;line-height:1.6;font-size:14px;color:#f4dfb8}
.home-wallet>span+span{color:#deb6f6}
.home-wallet b{font-weight:500;font-size:16px;overflow-wrap:anywhere}
.home-wallet small{font-size:10px;color:#d6c8dc}
.home-header-tools{display:flex;gap:3px}
.home-header-tools button{padding:8px;min-width:44px;min-height:44px;border-color:transparent;color:#eee4f1}
.home-save{position:absolute;bottom:1px;right:29px;font-size:9px;color:#acbcab;letter-spacing:.05em}
.home-page.content{max-width:1200px;padding:0 24px calc(40px + env(safe-area-inset-bottom))}
.home-screen-title{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.home-hero.hero{display:block;min-height:470px;isolation:isolate;border-radius:0;border:0;overflow:hidden;margin:0 -24px;background:#17101c}
.home-hero.hero:after{inset:0;border:0;border-radius:0;z-index:0;background:linear-gradient(0deg,#0b0b15 0%,#0b0b1510 35%,transparent 75%),linear-gradient(90deg,#110b1ac9,transparent 58%)}
.home-hero .home-hero-art.hero-art{width:100%;height:100%;max-width:none;right:0;top:0;object-fit:cover;object-position:center 15%;opacity:1;filter:none;z-index:-1}
.home-hero-copy{position:relative;z-index:1;min-height:470px;display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-end;padding:30px 5% 22px;max-width:640px}
.home-verse{font-family:var(--serif);font-size:24px;font-weight:600;line-height:1.6;letter-spacing:.08em;color:#fff6fc;text-shadow:0 2px 9px #090713,0 0 18px #090713;margin-bottom:18px}
.home-verse>span{display:block;margin-top:12px;font-size:14px;font-weight:400;letter-spacing:.04em;line-height:1.7}
.home-hero-title{font:clamp(28px,4vw,50px)/1.2 var(--serif);color:#fff0fc;letter-spacing:.04em;text-shadow:0 0 16px #9e2aab,0 2px 9px #090713;white-space:nowrap}
.home-hero-title>small{display:block;font-size:12px;letter-spacing:.14em;text-align:center;color:#f0d6f5;margin-top:6px}
.home-adventure.challenge-button{display:flex;align-items:center;gap:16px;width:100%;min-height:76px;margin:18px 0 0;padding:9px 20px;background:linear-gradient(105deg,#28122ef5,#2e1236d9 55%,#171024f2);color:#ffe6ad;border:1px solid #f4ce8a;border-radius:3px;box-shadow:0 0 0 3px #2b152c,0 0 0 4px #bf805e80,0 0 23px #bd3b9e45,inset 0 0 21px #ba3e9740;position:relative;text-align:left}
.home-adventure:before,.home-adventure:after{content:'✧';position:absolute;top:50%;transform:translateY(-50%);color:#ffdb9d;text-shadow:0 0 13px #f9a54e;font-size:28px;line-height:1}
.home-adventure:before{left:-13px}.home-adventure:after{right:-13px}
.home-adventure strong{display:block;font:600 30px/1.3 var(--serif);letter-spacing:.12em}
.home-adventure small{display:block;color:#e4cde4;font-size:12px;line-height:1.4;margin-top:2px}
.home-adventure-symbol{flex:0 0 auto;display:grid;place-items:center;color:#efb6ff;filter:drop-shadow(0 0 6px #ef9bff)}
.home-adventure-arrow{margin-left:auto;font-size:27px;line-height:1}
.home-adventure:hover:enabled{background:linear-gradient(105deg,#42204b,#34133e);border-color:#fff3bf;color:#fff1c9}
.home-goal{display:grid;grid-template-columns:minmax(0,1fr) minmax(135px,.42fr);gap:15px;align-items:center;border:1px solid #ad6d82;border-radius:5px;padding:16px 22px;margin:9px 0 18px;background:linear-gradient(105deg,#211426b3,#0c0c19);box-shadow:inset 0 0 0 4px #120d1d,inset 0 0 0 5px #7b4c6344;position:relative}
.home-goal-main{min-width:0}
.home-goal-kicker{color:#ed9dd5;font-size:13px;font-weight:600;letter-spacing:.12em}
.home-goal-row{display:flex;align-items:center;gap:12px;justify-content:space-between;margin-top:3px}
.home-goal-row h2{font-family:inherit;font-size:16px;font-weight:650;line-height:1.6;letter-spacing:0}
.home-goal-row>span{font-size:17px;white-space:nowrap;font-variant-numeric:tabular-nums;color:#f9eefb}
