.home-goal-reward{display:flex;align-items:center;gap:10px;border-left:1px solid #bda2c84d;padding-left:15px;color:#deb7f7}
.home-goal-reward small{display:block;font-size:11px;color:#cdbad8;line-height:1.5}
.home-goal-reward strong{display:block;font-size:13px;line-height:1.5;color:#f3e7fc;font-weight:500;overflow-wrap:anywhere}
.home-card-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 14px}
.home-card.modecard{--home-edge:#c5a370;min-height:145px;padding:20px 23px;border:1px solid var(--home-edge);border-radius:5px;isolation:isolate;position:relative;overflow:hidden;display:block;background:radial-gradient(ellipse at 88% 40%,#95642d5c,transparent 65%),linear-gradient(115deg,#15101d,#110d19 70%,#5d3d1c);box-shadow:inset 0 0 0 3px #100c17,inset 0 0 0 4px #ca9f642e}
.home-card-violet.modecard{--home-edge:#c283e5;background:radial-gradient(ellipse at 83% 45%,#9f2bba60,transparent 62%),linear-gradient(115deg,#160e27,#25122e)}
.home-card-blue.modecard{--home-edge:#7bb9ef;background:radial-gradient(ellipse at 88% 55%,#3762a18c,transparent 68%),linear-gradient(115deg,#0a132a,#11152b)}
.home-card-rose.modecard{--home-edge:#ca718a;background:radial-gradient(ellipse at 90% 60%,#6e245c80,transparent 65%),linear-gradient(115deg,#191020,#24101d)}
.home-card.modecard:before{content:'';position:absolute;inset:8px;z-index:1;pointer-events:none;border-top:1px solid #e6bdf72e;border-bottom:1px solid #e6bdf724;clip-path:polygon(10px 0,calc(100% - 10px) 0,100% 10px,100% calc(100% - 10px),calc(100% - 10px) 100%,10px 100%,0 calc(100% - 10px),0 10px)}
.home-card.modecard:after{content:'✧';position:absolute;right:10px;top:0;color:var(--home-edge);font-size:20px;pointer-events:none}
.home-card-sigil{position:absolute;right:10px;top:8px;bottom:0;width:46%;display:grid;place-items:center;color:var(--home-edge);opacity:.26;transform:rotate(-12deg);filter:drop-shadow(0 0 20px var(--home-edge));pointer-events:none}
.home-card-copy{position:relative;z-index:1;max-width:87%;pointer-events:none}
