.home-archive{display:flex;align-items:center;gap:16px;margin:16px 0 0;padding:18px 22px;border:1px solid #af7e8e;border-radius:5px;background:radial-gradient(ellipse at 38% 0%,#7f3a6b39,transparent 65%),linear-gradient(90deg,#16101e,#0b0c17);box-shadow:inset 0 0 0 4px #120d1d,inset 0 0 0 5px #7b4c6344}
