.summon-ray{position:absolute;width:2px;height:25vh;background:linear-gradient(transparent,currentColor,transparent);transform:rotate(var(--angle)) translateY(-32vh);animation:summon-ray 1.2s ease-out var(--delay) both}
#cinema.summon-cinema.rarity-R .outer{display:none}#cinema.summon-cinema.rarity-SR .summon-ring{border-radius:22%}#cinema.summon-cinema.rarity-SSR{background:radial-gradient(ellipse,#66522b,#211629 42%,#080a16 80%)}
@keyframes summon-tier{from{opacity:0;transform:scale(.55);filter:blur(8px)}to{opacity:1;transform:scale(1);filter:blur(0)}}
