.vfx-shield{inset:10%;border:2px solid #c6cfe4;border-radius:45% 45% 50% 50%;opacity:.65;box-shadow:inset 0 0 12px #b4c7eb22}

/* audit12 approved flow cutin: all overlays remain inside the existing battlefield. */
.battle-stage{overflow:hidden}
.battle-stage .vfx-shade{inset:0;background:#030108;z-index:6}
.battle-stage .vfx-cutin{inset:auto;left:0;top:15%;margin:0;width:100%;height:70%;max-height:70%;display:block!important;overflow:hidden;clip-path:polygon(0 9%,100% 0,100% 91%,0 100%);background:#20132e}
.battle-stage .vfx-cutin img{object-fit:cover!important;object-position:35% 35%;transform:scale(1.08)}
.vfx-cutin b{position:absolute;right:5%;bottom:12%;font:700 clamp(16px,5vw,27px)/1.2 Georgia,serif;letter-spacing:.12em;color:#fff5ff;text-shadow:0 2px 5px #000,0 0 10px #421058}
.battle-stage .vfx-projectile{left:0;width:100%;height:28%;transform-origin:80% 50%;z-index:8}
.vfx-impact{left:50%;top:45%;width:70%;aspect-ratio:1;border:2px solid #edc9ff;border-radius:50%;box-shadow:0 0 18px #b45bff,inset 0 0 13px #b45bff}
.vfx-impact-ultimate{border-width:4px;box-shadow:0 0 30px #b45bff,inset 0 0 20px #b45bff}
@media(prefers-reduced-motion:reduce){.battle-stage .vfx-cutin,.battle-stage .vfx-projectile,.battle-stage .vfx-shade{display:none!important}.vfx-impact{box-shadow:none}}

/* audit14: one concentrated piercing strike versus two readable feather shots. */
.battle-stage .vfx-cutin-pierce{top:12%;height:76%;max-height:76%;clip-path:polygon(0 12%,100% 0,100% 88%,0 100%)}
.battle-stage .vfx-cutin-volley{top:24%;height:52%;max-height:52%;clip-path:polygon(0 0,100% 12%,100% 100%,0 88%)}
