@media(prefers-reduced-motion:reduce){.vfx-pierce-charge,.vfx-pierce-trail{display:none!important}}

/* audit15: exclusive ultimate sequence; no generic feather/cutin textures. */
.battle-stage .vfx-apocalypse-veil{inset:0;background:radial-gradient(ellipse at 50% 35%,#210411,#030107 70%);z-index:18}
